```javascript
const express = require('express');
const ejs = require('ejs');
const app = express();
app.set('view engine', 'ejs');
app.use(express.urlencoded({ extended: false }));

// UGC 变体1：用户提交自定义卡片模板串，后端原样编译渲染
const cards = {};

// 外部输入入口：tpl 为用户可控的 EJS 模板源码，未做任何过滤
app.post('/card/save', (req, res) => {
  const id = 'c' + Date.now();
  cards[id] = req.body.tpl; // 用户模板串直接入库
  res.send('saved:' + id);
});

app.get('/card/:id', (req, res) => {
  const tpl = cards[req.params.id];
  if (!tpl) return res.status(404).end('not found');
  // 危险点：用户模板串经 compile 编译为可执行函数，<% %> 脚本段会被真实执行
  const renderCard = ejs.compile(tpl);
  // 外壳 views/shell.ejs 以 <%- content %> 嵌入编译结果，输出未转义
  app.render('shell', { content: renderCard({ visitor: req.query.visitor }) }, (err, html) => {
    if (err) return res.status(500).end('render error');
    res.send(html);
  });
});

app.listen(3000);
```

## 漏洞分析

1. **外部输入入口（source）**：line 13 `cards[id] = req.body.tpl`——POST /card/save 请求体字段 `tpl` 是用户可控的 EJS 模板源码，未做任何过滤或白名单校验即写入 UGC 存储 `cards`，攻击者完全控制模板串内容。

2. **主漏洞链（CWE-1336）**：line 18 `const tpl = cards[req.params.id]` 取出用户模板串，line 21 `ejs.compile(tpl)` 将其编译为可执行模板函数，line 23 调用 `renderCard({ visitor: ... })` 时模板内的 `<% %>` 脚本段被真实执行（如 `<%= 7*7 %>` 回显验证，进一步可触达 Node 运行时对象），模板语法执行可 RCE → 主类型 1336。

3. **伴生漏洞链（CWE-79）**：line 23 将编译执行结果作为 `content` 传入 `app.render('shell', ...)`，外壳 views/shell.ejs 以 `<%- content %>` 嵌入（见 line 22 注释），`<%- %>` 跳过 EJS 默认的变量转义，用户模板产出的 HTML 原样进入响应并持久化展示，XSS（输出未转义）为伴生漏洞同时成立。

4. **两漏洞互不遮挡**：autoescape 只影响变量值输出的转义，不影响 `<% %>` 模板语法是否被编译执行——即使开启变量自动转义，脚本段仍会执行（1336 保持），而 `<%- %>` 又显式绕过转义（79 保持）；按危害可达性规则 RCE 高于输出未转义，主类型取 CWE-1336，CWE-79 并列写入。

5. **无有效防御**：全链路无模板白名单、无沙箱隔离（EJS 本身不提供沙箱）、无输出编码、无输入校验，数据流从 `req.body.tpl` 到 `res.send(html)` 完整可达。

