```java
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
// API 鉴权中间件：校验 X-API-Token 请求头，通过后放行业务处理器
public class ApiAuthMiddleware implements HttpHandler {
    // 硬编码的静态 API 令牌：随源码/字节码泄露，且无法按环境轮换
    private static final String SECRET_API_TOKEN = "5f1c9a2e7b4d8e6f0a3c5b7d9e1f2a4b";

    private final HttpHandler business;  // 被保护的业务处理器

    public ApiAuthMiddleware(HttpHandler business) { this.business = business; }

    @Override
    public void handle(HttpExchange exchange) throws IOException {
        // 外部输入入口：客户端完全可控的请求头
        String token = exchange.getRequestHeaders().getFirst("X-API-Token");
        // 非常数时间比较：String.equals 逐字符短路返回，可测量逐位爆破
        if (token != null && token.equals(SECRET_API_TOKEN)) {
            business.handle(exchange);  // 鉴权通过，放行
            return;
        }
        byte[] body = "unauthorized".getBytes();
        exchange.sendResponseHeaders(401, body.length);
        try (OutputStream os = exchange.getResponseBody()) { os.write(body); }
    }

    // 启动示例：/data 接口由本中间件保护
    public static void main(String[] args) throws IOException {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/data", new ApiAuthMiddleware(ex -> {
            byte[] resp = "sensitive-data".getBytes();
            ex.sendResponseHeaders(200, resp.length);
            try (OutputStream os = ex.getResponseBody()) { os.write(resp); }
        }));
        server.start();
    }
}
```

1. **外部输入入口（source）**：line 19 `exchange.getRequestHeaders().getFirst("X-API-Token")` 读取客户端完全可控的请求头并赋给局部变量 token，未做任何过滤、归一化或哈希处理，是主数据流起点。
2. **数据流真实可达**：line 33 将本中间件挂载到 /data 路由，token 在 line 21 直接作为 `token.equals(SECRET_API_TOKEN)` 的实参参与鉴权判定，污点数据一步直达安全判定点，中间无任何封装。
3. **非常数时间比较（主类型 208）**：JDK 的 String.equals 先比较长度、再逐字符比较并在首个不匹配字符处立即返回 false，单次比较耗时

