const express = require('express');
const mysql = require('mysql2/promise');

const app = express();

// 演示环境数据库连接（凭据从环境变量读取，不含真实凭据）
let db;
async function initDb() {
  db = await mysql.createConnection({
    host: '127.0.0.1',
    user: 'shop_app',
    password: process.env.DB_PASSWORD,
    database: 'shop_db'
  });
}
initDb();

// 订单查询接口：GET /order?id=1001
app.get('/order', async (req, res) => {
  const oid = req.query.id; // 外部输入入口：URL 查询参数 id，未做类型/白名单校验
  try {
    // 将 oid 直接拼接进 SQL 模板字符串，未使用参数化查询
    const rows = await db.query(`SELECT * FROM orders WHERE id = '${oid}'`);
    res.json(rows[0]);
  } catch (e) {
    // 异常原样回显给客户端：会泄露 SQL 语句、表名、数据库版本等信息
    res.send(String(e));
  }
});

app.listen(3000, () => console.log('order service on 3000'));
```

1. **污点源（Source）**：line 20 `const oid = req.query.id` 直接读取 GET /order 的 URL 查询参数 id，攻击者完全可控，且未做任何类型校验、长度限制或白名单过滤。
2. **SQL 注入流（伴生 CWE-89）**：line 23 将 oid 以模板字符串直接拼接进 `db.query(\`SELECT * FROM orders WHERE id = '${oid}'\`)`，攻击者可用单引号闭合原查询并注入 ` OR '1'='1` 或 `UNION SELECT` 等载荷，读取 orders 表之外任意表的数据，属可读取任意数据的注入漏洞。
3. **异常回显流（主 CWE-209）**：当注入载荷破坏 SQL 语法或数据库出错时，line 25 的 `catch (e)` 捕获 mysql2 抛出的原始异常，line 27 `res.send(String(e))` 将错误原文直接返回客户端，其中包含完整 SQL 语句、表名/列名、MySQL 服务器版本与主机信息，构成敏感信息泄露。
4. **防御缺失验证**：全链路无参数化查询、无输入净化、无统一错误处理或日志脱敏中间件，两条数据流在同一次请求中均真实可达（如 `id=1'` 即可同时触发报错回显路径）。
5. **共现判定**：按异常回显+SQLi 的共现规则，主类型 209|89 同时成立——异常回显泄露 SQL/路径/库版本为主类型，同函数内的拼接查询为伴生漏洞，vulnerability_type 并列写入，不得省略。

