package main

import (
	"database/sql"
	"net/http"
	"os"

	_ "github.com/go-sql-driver/mysql" // 注册 MySQL 驱动
)

var db *sql.DB // 订单库连接，main 中初始化

// orderQuery 处理 GET /order?id=... 的订单查询
func orderQuery(w http.ResponseWriter, r *http.Request) {
	oid := r.URL.Query().Get("id") // 外部输入入口：URL 查询参数 id，未做任何校验
	// 直接字符串拼接构造 SQL，oid 可携带 ' OR '1'='1 等注入载荷
	rows, err := db.Query("SELECT * FROM orders WHERE id='" + oid + "'")
	if err != nil {
		// 出错时把驱动底层错误原样回显给客户端
		http.Error(w, err.Error(), 500) // 泄露 SQL 文本、表名、驱动/数据库版本等信息
		return
	}
	defer rows.Close()
	w.Write([]byte("ok"))
}

func main() {
	var err error
	db, err = sql.Open("mysql", os.Getenv("DB_DSN")) // DSN 取自环境变量，避免明文凭据
	if err != nil {
		panic(err)
	}
	http.HandleFunc("/order", orderQuery)
	http.ListenAndServe(":8080", nil)
}
```

1. 入口（line 15）：外部输入 oid 直接取自 r.URL.Query().Get("id")，无白名单、无类型与字符校验，攻击者完全可控。
2. SQL 注入流（line 17）：oid 被拼入 "SELECT * FROM orders WHERE id='" + oid + "'" 后交给 db.Query 执行；单引号可被闭合，注入恒真条件或 UNION SELECT 即可绕过查询条件、读取任意订单数据，构成 CWE-89 的可达 sink。
3. 异常回显流（line 18-20）：注入载荷（如单个引号）破坏 SQL 语法后 db.Query 返回 err，err.Error() 携带完整 SQL 文本、表名 orders、驱动与数据库版本、连接信息等，经 http.Error(w, err.Error(), 500) 以 500 响应原样回显给客户端，构成 CWE-209 的可达 sink。
4. 共现判定：按异常回显+SQLi 的主次规则，异常回显仅需任何请求（如 id='）即可稳定触发且直接泄露敏感信息，取主类型 209；同函数 line 17 的拼接查询危害同时可达，89 同时成立，二者并列写入 vulnerability_type 且 CWE-209 在前。
5. 防御缺失：全链路无参数化占位符（?）、无输入校验、无错误脱敏或日志化处理，两条数据流均真实可达，无有效防御。

